import React, { useState } from "react";
import { Link, useLocation } from "react-router-dom";
import "./SidebarMenu.css";

// JSON menu structure
const menuItems = [
  {
    label: "Dashboard",
    icon: "fas fa-tachometer-alt",
    to: "/dashboard",
  },
  {
    label: "Widgets",
    icon: "fas fa-th",
    to: "/widgets",
    badge: "New",
  },
  {
    label: "User Management",
    icon: "fas fa-users",
    children: [
      { label: "Users", to: "/users" },
      { label: "Roles", to: "/roles" },
      { label: "Permissions", to: "/permissions" },
      { label: "Departments", to: "/departments" },
    ],
  },
  {
    label: "Attendance",
    icon: "fas fa-clock",
    children: [
      { label: "Daily Attendance", to: "/employees/attendance/daily" },
      { label: "Monthly Attendance", to: "/employees/attendance/monthly" },
    ],
  },
];

// Recursive component to render menu items
const MenuItem = ({ item, openMenu, toggleMenu, isActive }) => {
  const hasChildren = item.children && item.children.length > 0;
  const isOpen = openMenu === item.label;

  return (
    <li className={`nav-item ${hasChildren && isOpen ? "menu-open" : ""}`}>
      {hasChildren ? (
        <>
          <a
            href="#!"
            className={`nav-link ${isOpen ? "active" : ""}`}
            onClick={() => toggleMenu(item.label)}
          >
            <i className={`nav-icon ${item.icon}`} />
            <p>
              {item.label}
              <i className="right fas fa-angle-left" />
            </p>
          </a>
          <ul className="nav nav-treeview">
            {item.children.map((child) => (
              <MenuItem
                key={child.label}
                item={child}
                openMenu={openMenu}
                toggleMenu={toggleMenu}
                isActive={isActive}
              />
            ))}
          </ul>
        </>
      ) : (
        <Link
          to={item.to}
          className={`nav-link ${isActive(item.to) ? "active" : ""}`}
        >
          {item.icon && <i className={`nav-icon ${item.icon}`} />}
          <p>
            {item.label}
            {item.badge && <span className="right badge badge-danger">{item.badge}</span>}
          </p>
        </Link>
      )}
    </li>
  );
};

const SidebarMenu = () => {
  const location = useLocation();
  const [openMenu, setOpenMenu] = useState(null);

  const toggleMenu = (label) => setOpenMenu(openMenu === label ? null : label);
  const isActive = (path) => location.pathname === path;

  return (
    <aside className="main-sidebar sidebar-dark-primary elevation-4">
      <Link to="/" className="brand-link">
        <img
          src="/template/dist/img/logo.jpg"
          alt="Logo"
          className="brand-image img-circle elevation-3"
          style={{ opacity: ".8" }}
        />
        <span className="brand-text font-weight-light">ORA</span>
      </Link>

      <div className="sidebar">
        {/* USER PANEL */}
        <div className="user-panel mt-3 pb-3 mb-3 d-flex">
          <div className="image">
            <img
              src="/template/dist/img/user.png"
              className="img-circle elevation-2"
              alt="User"
            />
          </div>
          <div className="info">
            <Link to="#" className="d-block">
              Super Admin
            </Link>
          </div>
        </div>

        {/* NAVIGATION */}
        <nav className="mt-2">
          <ul
            className="nav nav-pills nav-sidebar flex-column"
            data-widget="treeview"
            role="menu"
            data-accordion="false"
          >
            {menuItems.map((item) => (
              <MenuItem
                key={item.label}
                item={item}
                openMenu={openMenu}
                toggleMenu={toggleMenu}
                isActive={isActive}
              />
            ))}
          </ul>
        </nav>
      </div>
    </aside>
  );
};

export default SidebarMenu;
